CREATE OR ALTER PROCEDURE [dbo].[uspFoodSafetyChecklistItem_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ChecklistId UNIQUEIDENTIFIER = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ChecklistId]
			, t.[ItemCode]
			, t.[ItemName]
			, t.[Description]
			, t.[SortOrder]
			, t.[IsCritical]
			, t.[ExpectedValue]
			, t.[UnitCode]
			, t.[IsRequired]
			, t.[CreatedDate]
		FROM [dbo].[FoodSafetyChecklistItem] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ItemCode] LIKE CONCAT('%', @SearchText, '%') OR t.[ItemName] LIKE CONCAT('%', @SearchText, '%') OR t.[UnitCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ChecklistId IS NULL OR t.[ChecklistId] = @ChecklistId)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'checklistId' THEN r.[ChecklistId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'checklistId' THEN r.[ChecklistId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'itemCode' THEN r.[ItemCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'itemCode' THEN r.[ItemCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'itemName' THEN r.[ItemName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'itemName' THEN r.[ItemName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'description' THEN r.[Description] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'description' THEN r.[Description] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'sortOrder' THEN r.[SortOrder] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isCritical' THEN r.[IsCritical] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isCritical' THEN r.[IsCritical] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'expectedValue' THEN r.[ExpectedValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'expectedValue' THEN r.[ExpectedValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitCode' THEN r.[UnitCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitCode' THEN r.[UnitCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isRequired' THEN r.[IsRequired] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isRequired' THEN r.[IsRequired] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
